create or replace TABLE ANALYTICS.PUBLIC.DIM_CUSTOMER (
	CUSTOMER_KEY NUMBER(38,0) NOT NULL autoincrement,
	EMAIL VARCHAR(16777216),
	ATTRS VARIANT,
	LOADED_AT TIMESTAMP_NTZ(9) DEFAULT CURRENT_TIMESTAMP(),
	constraint PK_DIM_CUSTOMER primary key (CUSTOMER_KEY)
);
create or replace TRANSIENT TABLE ANALYTICS.PUBLIC.FACT_ORDER (
	ORDER_KEY NUMBER(38,0) NOT NULL,
	CUSTOMER_KEY NUMBER(38,0),
	AMOUNT NUMBER(12,2),
	constraint FK_FACT_CUST foreign key (CUSTOMER_KEY) references ANALYTICS.PUBLIC.DIM_CUSTOMER(CUSTOMER_KEY)
) CLUSTER BY (ORDER_KEY);
